def create_units_for_existing_buildings(apps, schema_editor):
    """Imóveis anteriores às unidades (P1.07a): cada um ganha as suas `units` unidades, índices 1..n."""
    Building = apps.get_model("properties", "Building")
    Unit = apps.get_model("properties", "Unit")
    for b in Building.objects.all():
        Unit.objects.bulk_create([Unit(building_id=b.pk, index=i) for i in range(1, b.units + 1)])


